update public.quotes set text_en = 'Knowledge is what benefits — knowledge is not what is merely memorized.' where id = '4dc32bb1-4285-448e-acdc-0dc6269cbf0c';
update public.quotes set text_en = 'I guarded myself from all that would defile it, and rose above all that is cast upon me.' where id = '2ae89310-6faf-4d55-9382-b6f28f5f83d4';
