update public.quotes set text_en = 'Among the gravest punishments is for the sweetness of obedience to vanish from your heart.' where id = 'ac319c60-01c2-4059-8208-3e8eae8654ed';
update public.quotes set text_en = 'When the light of knowledge shines in the heart, it sees truth from falsehood clearly.' where id = 'df6179da-d2b5-40a4-956b-0e88168ad4a2';
