update public.quotes set text_en = 'Reason is an ornament, and good manners are the finest inheritance.' where id = '3203b4cd-2e2b-4639-ba1c-5a97eb2a51ef';
update public.quotes set text_en = 'Helplessness is a flaw; patience is courage.' where id = '3240f49e-743a-453c-84d4-508ff5d56935';
