update public.quotes set text_en = 'If you wish to know your worth before God, look at what occupies your heart.' where id = '1551ddcb-d752-4a1b-bd61-26779db6ce87';
update public.quotes set text_en = 'Do not keep company with one who cannot lift up his own soul.' where id = '3922ec9a-8f56-481b-bfb9-32366f505839';
