update public.quotes set text_en = 'Enduring harm patiently is the fruit of knowledge.' where id = 'd12a25cf-56a3-41c7-8ce6-2a5fbab89028';
update public.quotes set text_en = 'Beautiful patience is that which carries no complaint to any creature.' where id = '79df1d14-b867-4122-a09f-16f34ef35b88';
